#[test]
fn test_below_is_in_range_and_advances() {
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    sm_seed(st, 0);
    crate::testport::assert_eq(sm_below(st, 1000), 516, "first below-1000 of seed 0");
    crate::testport::assert_eq(sm_below(st, 0), 0, "n = 0 answers 0");
    crate::testport::assert_eq(sm_below(st, -5), 0, "n < 0 answers 0");
    sm_seed(st, 99);
    while i < 200 {
        crate::testport::assert_that_at(sm_below(st, 7) >= 0, "non-negative", i);
        i += 1;
    }
}
#[test]
fn test_a_reseed_restarts_the_stream() {
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    sm_seed(st, 5);
    let w0: i64 = sm_next(st);
    let w1: i64 = sm_next(st);
    sm_seed(st, 5);
    crate::testport::assert_eq64(sm_next(st), w0, "same seed, same first word");
    crate::testport::assert_eq64(sm_next(st), w1, "and the same second word");
    crate::testport::assert_that(w0 != w1, "and the two differ");
}
